package inventory

import (
	"cmp"
	"slices"
)

// ReorderAt 是补货阈值：数量低于它的条目需要补货。
const ReorderAt = 5

// Item 是库存里的一条记录。
type Item struct {
	SKU string
	Qty int
}

// Reorder 返回需要补货的条目（Qty < ReorderAt），
// 按数量升序排列，数量相同时按 SKU 升序排列。
func Reorder(items []Item) []Item {
	var low []Item
	for _, it := range items {
		if it.Qty < ReorderAt {
			low = append(low, it)
		}
	}
	slices.SortFunc(low, func(a, b Item) int {
		if c := cmp.Compare(a.Qty, b.Qty); c != 0 {
			return c
		}
		return cmp.Compare(a.SKU, b.SKU)
	})
	return low
}

