// Total 返回一批货的金额（单位：分）。
func Total(cents, qty int) int {
	return cents * qty
}

// BulkTotal 返回一批货打折后的金额（单位：分）。
// 折扣按 cents*qty*discountPct/100 向下取整。
func BulkTotal(cents, qty, discountPct int) int {
	amount := Total(cents, qty)
	return amount - amount*discountPct/100
}

package report

import (
	"fmt"

	"example.com/shop/inventory"
	"example.com/shop/pricing"
)

// SKULine 是报表里最基础的一行：SKU 与数量。
func SKULine(sku string, qty int) string {
	return fmt.Sprintf("%s x%d", sku, qty)
}

// LowStockLines 为每个待补货的条目输出一行 "<sku> x<qty> = <金额>"。
// 顺序与 inventory.Reorder 一致，金额由 pricing.BulkTotal 计算。
func LowStockLines(items []inventory.Item, unitCents map[string]int, discountPct int) []string {
	low := inventory.Reorder(items)
	lines := make([]string, 0, len(low))
	for _, it := range low {
		amount := pricing.BulkTotal(unitCents[it.SKU], it.Qty, discountPct)
		lines = append(lines, fmt.Sprintf("%s = %d", SKULine(it.SKU, it.Qty), amount))
	}
	return lines
}

