package inventory

import (
	"reflect"
	"testing"
)

func TestReorder(t *testing.T) {
	items := []Item{
		{SKU: "b", Qty: 3},
		{SKU: "a", Qty: 3},
		{SKU: "c", Qty: 1},
		{SKU: "d", Qty: 5}, // 恰好等于阈值，不属于「低于」
		{SKU: "e", Qty: 0},
	}
	got := Reorder(items)
	want := []Item{
		{SKU: "e", Qty: 0},
		{SKU: "c", Qty: 1},
		{SKU: "a", Qty: 3},
		{SKU: "b", Qty: 3},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Reorder = %v，想要 %v", got, want)
	}
}

func TestReorderDoesNotMutateInput(t *testing.T) {
	items := []Item{{SKU: "b", Qty: 1}, {SKU: "a", Qty: 2}}
	Reorder(items)
	if items[0].SKU != "b" || items[1].SKU != "a" {
		t.Fatalf("Reorder 不应修改入参：%v", items)
	}
}

func TestReorderNone(t *testing.T) {
	items := []Item{{SKU: "a", Qty: 5}, {SKU: "b", Qty: 9}}
	if got := Reorder(items); len(got) != 0 {
		t.Fatalf("Reorder 应返回空，得到 %v", got)
	}
}

package pricing

import "testing"

func TestBulkTotal(t *testing.T) {
	cases := []struct {
		cents, qty, discountPct, want int
	}{
		{250, 3, 0, 750},  // 无折扣
		{250, 3, 10, 675}, // 750 - 75
		{100, 3, 33, 201}, // 300 - 99
		{101, 1, 33, 68},  // 折扣 33.33 向下取整为 33
		{50, 0, 10, 0},    // 数量为零
	}
	for _, c := range cases {
		if got := BulkTotal(c.cents, c.qty, c.discountPct); got != c.want {
			t.Fatalf("BulkTotal(%d, %d, %d) = %d，想要 %d",
				c.cents, c.qty, c.discountPct, got, c.want)
		}
	}
}

package report

import (
	"reflect"
	"testing"

	"example.com/shop/inventory"
)

func TestLowStockLines(t *testing.T) {
	items := []inventory.Item{
		{SKU: "b", Qty: 3},
		{SKU: "a", Qty: 3},
		{SKU: "c", Qty: 1},
		{SKU: "d", Qty: 9}, // 不需要补货
	}
	unitCents := map[string]int{"a": 250, "b": 100, "c": 1000, "d": 100}
	got := LowStockLines(items, unitCents, 10)
	want := []string{
		"c x1 = 900",
		"a x3 = 675",
		"b x3 = 270",
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockLines = %v，想要 %v", got, want)
	}
}

func TestLowStockLinesMissingPrice(t *testing.T) {
	items := []inventory.Item{{SKU: "x", Qty: 2}}
	got := LowStockLines(items, map[string]int{}, 0)
	want := []string{"x x2 = 0"}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("LowStockLines = %v，想要 %v", got, want)
	}
}
